def group_initials(words):
    groups = {}
    for word in words:
        if not word:
            continue
        initial = word[0].lower()
        if initial not in groups:
            groups[initial] = []
        groups[initial].append(word)
    return groups

print(group_initials(["Oak", "olive", "Birch"]))

