def make_counters(names):
    class Counter:
        def __init__(self, name):
            self.name = name
            self.count = 0
        def tick(self):
            self.count += 1
    return [Counter(name) for name in names]

counters = make_counters(["East", "West"])
counters[0].tick()
print([c.count for c in counters])

def make_device(name, level):
    class Device:
        def __init__(self, name, level):
            self.name = name
            self.level = level
        def __repr__(self):
            return "Device({}, {})".format(self.name, self.level)
    return Device(name, level)

